    "questionEn": "A body of weight $W = 80\\text{ N}$ is on a rough plane inclined at $30^\\circ$ to the horizontal with $\\mu_s = \\frac{\\sqrt{3}}{6}$. Find the least force $P$ directed up along the line of greatest slope to prevent the body from slipping down.",
    "questionAr": "جسم وزنه $80\\text{ نيوتن}$ على مستوى خشن يميل بزاوية $30^\\circ$ ومعامل احتكاكه $\\mu_s = \\frac{\\sqrt{3}}{6}$. أوجد أقل قوة $P$ موجهة لأعلى في اتجاه خط أكبر ميل تمنع الجسم من الانزلاق لأسفل.",
