      "٢. النسبة: $\\frac{1 + \\mu_s}{1 - \\mu_s} = 10$.",
      "٣. حل المعادلة: $(10 + 1)\\mu_s = 10 - 1 \\implies \\mu_s = \\frac{9}{11}$.\""
