    "questionAr": "جسم وزنه $20\\text{ نيوتن}$ موضوع على مستوى خشن يميل بزاوية $45^\\circ$ ومعامل احتكاكه $\\mu_s = \\frac{1}{3}$. أوجد مقدار القوة الأفقية $P$ الموجهة نحو المستوى التي تجعل الجسم على وشك الحركة لأعلى.",
