      "$$(3 - 1)P = (3 + 1)20 \\implies P = \\frac{3 + 1}{3 - 1}(20)$$",
      "4. Since $W = 20 = 10(3 - 1)$, we get: $P = 10(3 + 1) = 40\\text{ N}$."
